        TRC_TYPE_CODE
     || TRC_TYPE_CATEGORY
     || CAST(TRC_CAT_DATA AS CHAR(50))
     || REPEAT('0',4)
                      AS CHAR(60))
  FROM  CARDDEMO.TRANSACTION_TYPE_CATEGORY
  ORDER BY
        TRC_TYPE_CODE
      , TRC_TYPE_CATEGORY;
